import assert from "node:assert/strict";
import { mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";
import { buildCustomerIndex } from "../src/customers.js";
import { UnknownReferenceError } from "../src/errors.js";
import { exportInvoices } from "../src/export.js";
import { loadCustomerRecords } from "../src/sources.js";

test("CRM customers (customer_id) are indexed like billing customers", () => {
  const dir = mkdtempSync(join(tmpdir(), "src-"));
  writeFileSync(join(dir, "billing-customers.json"), JSON.stringify([{ customerId: "C-1", name: "A", country: "DE" }]));
  writeFileSync(join(dir, "crm-customers.json"), JSON.stringify([{ customer_id: "C-2", name: "B", country: "NL" }]));
  const index = buildCustomerIndex(loadCustomerRecords(dir));
  assert.equal(index.get("C-1").name, "A");
  assert.deepEqual(index.get("C-2"), { customerId: "C-2", name: "B", country: "NL" });
});

test("exporting an invoice of an unknown customer throws UnknownReferenceError", () => {
  const invoice = { id: "INV-9", customerId: "nope", issuedOn: "2026-10-01", lines: [] };
  assert.throws(() => exportInvoices([invoice], new Map()), UnknownReferenceError);
});
